-- The 30-day liability replay (G-16): the nightly liability, the breakage and the
-- ledger of a scripted scenario, computed by @fnb/core and compared, day by day,
-- with what the app functions store in loyalty_liability_daily.
--
-- Techniques (ISTQB): model-based testing (the expected rows come from the
-- @fnb/core ledger model, packages/core/src/rules/loyalty-ledger.ts and
-- loyalty-liability.ts, run on the same operations; the dollar-quoted JSON of
-- the replay table below is packages/core/test/fixtures/loyalty-liability-replay.json
-- and a unit test keeps it identical), boundary value analysis (an expiry-month
-- boundary inside the 30 days: the October 2026 cohort of points runs out on
-- 31 October 2027 and the November one starts on 1 November; the breakage rate
-- switches from the configured to the observed one on 2027-10-21, exactly six
-- months after the first expiry), state transition testing (earns pending then
-- confirmed, holds confirmed, released by hand or released by the 24-hour rule,
-- a hold followed by a clawback that leaves a negative balance), regression (a
-- re-run replaces the day's row with the same values).
--
-- The scenario: 12 synthetic members, a programme with the default parameters
-- (12-month points, 6-month stamps, point value 500, expected breakage 0.200).
-- History: three earns on 2026-04-20 and one to three a day from 17 October to
-- 15 November 2026. Nightly runs on 2027-04-21 and 2027-05-16, then one at 04:00
-- local on each of the 30 days from 2027-10-17 to 2027-11-15, with the day's
-- sales, voids, holds and adjustments between them and an end-of-day run at
-- 23:30 (which replaces that day's row, so the nightly row is copied first).
--
-- Every moment is explicit (nothing reads now()), phones are synthetic
-- (0900000800 to 0900000811), nothing is sent, and the file rolls back.
begin;
select plan(79);

set local timezone = 'UTC';
update app.incremental_sync_settings set enabled = false, updated_at = '2026-01-01 00:00+00';

create temp table fx as
select
  'dddddddd-dddd-4ddd-8ddd-000000023601'::uuid as tenant_l,
  'cccccccc-cccc-4ccc-8ccc-000000023601'::uuid as account_l,
  'ffffffff-ffff-4fff-8fff-000000023601'::uuid as store_l,
  'aaaaaaaa-aaaa-4aaa-8aaa-000000023601'::uuid as programme_l;

insert into public.tenants (id, slug, name)
select tenant_l, 'liability-replay-pgtap', 'Liability replay pgTAP' from fx;
insert into public.pos_accounts (id, tenant_id, connector, account_key, display_name)
select account_l, tenant_l, 'mock', 'liability-replay', 'Synthetic liability account' from fx;
insert into public.stores (id, tenant_id, pos_account_id, external_id, name)
select store_l, tenant_l, account_l, 'lq-s1', 'Synthetic liability store' from fx;
insert into public.loyalty_programmes (id, tenant_id, name, starts_on, notification_decision, status, welcome_stamps)
select programme_l, tenant_l, 'Synthetic liability programme', date '2026-01-01', 'below_threshold'::public.loyalty_notification_decision, 'active'::public.loyalty_programme_status, 0 from fx;

insert into public.coupon_rails (tenant_id, store_id, rail, crm_programme_external_ids, active_from)
select tenant_l, store_l, 'pos_payment_discount'::public.coupon_rail, '{}'::text[], timestamptz '2026-01-01 00:00+07' from fx;
insert into public.coupon_rail_rewards (tenant_id, store_id, reward_key, pos_discount_name, crm_programme_external_id, einvoice_display)
select tenant_l, store_l, 'points-cake', 'Synthetic cake', null, 'discount'::public.einvoice_display from fx
union all
select tenant_l, store_l, 'stamp-drink', 'Synthetic drink', null, 'discount' from fx;
select set_config('request.jwt.claims', '', true);
insert into public.coupons (tenant_id, programme_id, reward_key, name, reward_kind, reward_percent, cost_stamps, cost_points, store_ids, per_member_limit, status)
select tenant_l, programme_l, 'points-cake', 'Cake for points', 'free_item'::public.coupon_reward_kind, null::numeric, 0, 40, null::uuid[], null::smallint, 'active'::public.coupon_status from fx
union all
select tenant_l, programme_l, 'stamp-drink', 'Drink for stamps', 'free_item', null::numeric, 2, 0, null::uuid[], null::smallint, 'active' from fx;

