create temp table members (idx integer primary key, phone text, membership_id uuid);
insert into members
select (p.ord - 1)::integer, p.phone, app.loyalty_join(
  fx.tenant_l,
  app.loyalty_customer_for_phone(fx.tenant_l, p.phone, (r.doc ->> 'joinedAt')::timestamptz),
  'mini_app', fx.store_l, null, null, (r.doc ->> 'joinedAt')::timestamptz
)
from fx, replay r, jsonb_array_elements_text(r.doc -> 'phones') with ordinality p (phone, ord);

-- earn ref -> invoice; hold ref -> redemption
create temp table refs (ref text primary key, invoice_id uuid, redemption_id uuid);
-- the row each nightly run stored, copied before an end-of-day run replaces it
create temp table nightly_rows (as_of_date date primary key, doc jsonb);

create function pg_temp.row_doc(p_date date)
returns jsonb
language sql
as $$
  select jsonb_build_object(
    'asOfDate', d.as_of_date,
    'members', d.members,
    'outstandingPoints', d.outstanding_points,
    'outstandingStamps', d.outstanding_stamps,
    'pointValueAmount', d.point_value_amount::text,
    'expectedBreakageRate', d.expected_breakage_rate::text,
    'breakageSource', d.breakage_source,
    'liabilityAmount', d.liability_amount::text,
    'pointsIssued', d.points_issued,
    'pointsRedeemed', d.points_redeemed,
    'pointsExpired', d.points_expired,
    'pointsClawedBack', d.points_clawed_back,
    'deferredRevenueReleasedAmount', d.deferred_revenue_released_amount::text,
    'breakageByCohort', d.breakage_by_cohort
  )
  from public.loyalty_liability_daily d
  where d.programme_id = (select programme_l from fx) and d.as_of_date = p_date;
$$;

create function pg_temp.replay_ops()
returns integer
language plpgsql
as $$
declare
  v_op jsonb;
  v_at timestamptz;
  v_invoice uuid;
  v_membership uuid;
  v_redemption uuid;
  v_result jsonb;
  v_ran integer := 0;
begin
  for v_op in
    select o.op from replay r, jsonb_array_elements(r.doc -> 'ops') with ordinality o (op, ord) order by o.ord
  loop
    v_at := (v_op ->> 'at')::timestamptz;
    select m.membership_id into v_membership from members m where m.idx = (v_op ->> 'member')::integer;
    case v_op ->> 'kind'
      when 'earn' then
        insert into public.invoices (tenant_id, store_id, pos_account_id, external_id, receipt_no, sold_at, business_date, gross_amount, net_amount, paid_amount, source_name, status)
        select fx.tenant_l, fx.store_l, fx.account_l, v_op ->> 'ref', right(v_op ->> 'ref', 4), (v_op ->> 'soldAt')::timestamptz,
          ((v_op ->> 'soldAt')::timestamptz at time zone 'Asia/Ho_Chi_Minh')::date,
          (v_op ->> 'amount')::numeric, (v_op ->> 'amount')::numeric, (v_op ->> 'amount')::numeric, 'tai-quan', 'completed'
        from fx
        returning id into v_invoice;
        insert into refs (ref, invoice_id) values (v_op ->> 'ref', v_invoice);
        perform app.loyalty_earn(v_invoice, v_membership, 'A', v_at, (v_op ->> 'pending')::boolean);
      when 'confirm' then
        perform app.loyalty_confirm(
          (select l.id from public.loyalty_ledger l join refs r on r.invoice_id = l.invoice_id where r.ref = v_op ->> 'ref' and l.entry_kind = 'earn'),
          null, v_at
        );
      when 'void' then
        update public.invoices set status = 'voided' where id = (select r.invoice_id from refs r where r.ref = v_op ->> 'ref');
      when 'hold' then
        v_result := app.redeem_coupon(
          v_membership,
          (select c.id from public.coupons c where c.tenant_id = (select tenant_l from fx) and c.reward_key = case v_op ->> 'coupon' when 'cake' then 'points-cake' else 'stamp-drink' end),
          (select store_l from fx),
          v_at
        );
        if v_result ->> 'refusal' is not null then
          raise exception 'hold % was refused: %', v_op ->> 'ref', v_result ->> 'refusal';
        end if;
        insert into refs (ref, redemption_id) values (v_op ->> 'ref', (v_result ->> 'redemption_id')::uuid);
      when 'confirm_hold' then
        perform app.confirm_redemption(
          (select r.redemption_id from refs r where r.ref = v_op ->> 'ref'),
          (select r.invoice_id from refs r where r.ref = v_op ->> 'invoice'),
          v_at
        );
      when 'release' then
        perform app.release_redemption((select r.redemption_id from refs r where r.ref = v_op ->> 'ref'), 'hold_expired', v_at);
      when 'adjust' then
        perform app.loyalty_apply_adjustment(v_membership, (select store_l from fx), (v_op ->> 'stamps')::integer, (v_op ->> 'points')::integer, v_op ->> 'reason', null, v_at);
      when 'nightly' then
        perform app.loyalty_nightly((select tenant_l from fx), v_at);
        insert into nightly_rows (as_of_date, doc)
        values ((v_at at time zone 'Asia/Ho_Chi_Minh')::date, pg_temp.row_doc((v_at at time zone 'Asia/Ho_Chi_Minh')::date));
      when 'liability' then
        perform app.loyalty_liability((select programme_l from fx), v_at);
    end case;
    v_ran := v_ran + 1;
  end loop;
  return v_ran;
end;
$$;

select is((select count(*)::int from members), 12, 'the replay enrols 12 synthetic members');
select is(
  pg_temp.replay_ops(),
  (select jsonb_array_length(doc -> 'ops') from replay),
  'every operation of the scenario ran through the app functions (earns, confirms, voids, holds, releases, adjustments, 32 nightly runs, 29 end-of-day runs)'
);

-- Ledger level: the model and the functions wrote the same kinds of rows and
-- leave the same balances.
select is(
  (select jsonb_object_agg(k.entry_kind, k.n) from (select entry_kind::text, count(*)::int as n from public.loyalty_ledger where tenant_id = (select tenant_l from fx) group by entry_kind) k),
  (select doc -> 'ledgerCounts' from replay),
  'the ledger holds the rows of the model: earns, confirms, redemption holds, adjustments (releases among them), clawbacks and expiries'
);
select is(
  (select jsonb_object_agg(m.idx::text, jsonb_build_array(b.stamps, b.points)) from members m cross join lateral app.loyalty_balance(m.membership_id) b),
  (select doc -> 'balances' from replay),
  'the 12 spendable balances equal the model''s, the negative one included'
);
select is(
  (select b.points from members m cross join lateral app.loyalty_balance(m.membership_id) b where m.idx = 11),
  -10,
  'a clawback after a confirmed redemption leaves the member at -10 points (45 earned - 40 spent - 15 clawed back)'
);

-- Liability level, 1: the row each nightly run stored, for the two runs before
-- the window and the 30 of the window.
select is(
  (select count(*)::int from nightly_rows),
  (select jsonb_array_length(doc -> 'rows') from replay),
  'a nightly row was copied for each of the 32 nightly runs'
);
select is(
  n.doc,
  e.row,
  'nightly row of ' || (e.row ->> 'asOfDate') || ' (' || (e.row ->> 'breakageSource') || ' breakage, ' || (e.row ->> 'liabilityAmount') || ')'
)
from replay r
cross join lateral jsonb_array_elements(r.doc -> 'rows') with ordinality e (row, ord)
left join nightly_rows n on n.as_of_date = (e.row ->> 'asOfDate')::date
order by e.ord;

-- Liability level, 2: what loyalty_liability_daily holds at the end, one row per
-- day: the end-of-day run's row where there was one, the nightly row on the last day.
select is(
  (select count(*)::int from public.loyalty_liability_daily where programme_id = (select programme_l from fx)),
  32,
  'one stored row per day: 2 earlier runs and 30 days of the window'
);
select is(
  pg_temp.row_doc((e.row ->> 'asOfDate')::date),
  e.row,
  'end-of-day row of ' || (e.row ->> 'asOfDate') || ' (' || (e.row ->> 'liabilityAmount') || ')'
)
from replay r
cross join lateral jsonb_array_elements(r.doc -> 'closing') with ordinality e (row, ord)
order by e.ord;
select is(
  pg_temp.row_doc(date '2027-11-15'),
  (select doc -> 'rows' -> 31 from replay),
  'the last day of the window keeps its nightly row'
);

-- Boundary checks inside the window, written against the stored rows.
select is(
  (select string_agg(d.as_of_date::text || ':' || d.breakage_source, ',' order by d.as_of_date)
   from public.loyalty_liability_daily d
   where d.programme_id = (select programme_l from fx) and d.as_of_date between date '2027-10-19' and date '2027-10-22'),
  '2027-10-19:configured,2027-10-20:configured,2027-10-21:observed,2027-10-22:observed',
  'the breakage turns observed on the day the first expiry (2027-04-21 04:00) is exactly six months old'
);
select is(
  (select c
   from public.loyalty_liability_daily d, jsonb_array_elements(d.breakage_by_cohort) c
   where d.programme_id = (select programme_l from fx) and d.as_of_date = date '2027-04-21' and c ->> 'month' = '2026-04'),
  '{"month": "2026-04", "issued": 24, "expired": 24}'::jsonb,
  'the first expiry reports the April 2026 cohort whole: 24 points issued, 24 expired'
);
select is(
  (select count(*)::int from public.loyalty_ledger l
   where l.tenant_id = (select tenant_l from fx) and l.entry_kind = 'earn'
     and l.occurred_at >= timestamptz '2026-11-01 00:00+07' and l.expires_at <= timestamptz '2027-11-01 04:00+07'),
  0,
  'no credit issued in November 2026 had expired by the run of 2027-11-01 04:00'
);
-- G-104 F1 (ADR-048): an expiry is reported under the month its credit was issued.
select is(
  (select coalesce(sum((c ->> 'expired')::int), 0)::int
   from public.loyalty_liability_daily d, jsonb_array_elements(d.breakage_by_cohort) c
   where d.programme_id = (select programme_l from fx) and d.as_of_date = date '2027-11-01' and c ->> 'month' = '2026-11'),
  0,
  'the run of 2027-11-01 04:00 reports nothing under the November 2026 cohort: only credits sold on 31 October 2026 after 04:00 expired'
);
select cmp_ok(
  (select coalesce(sum((c ->> 'expired')::int), 0)::int
   from public.loyalty_liability_daily d, jsonb_array_elements(d.breakage_by_cohort) c
   where d.programme_id = (select programme_l from fx) and d.as_of_date = date '2027-11-01' and c ->> 'month' = '2026-10'),
  '>',
  (select coalesce(sum((c ->> 'expired')::int), 0)::int
   from public.loyalty_liability_daily d, jsonb_array_elements(d.breakage_by_cohort) c
   where d.programme_id = (select programme_l from fx) and d.as_of_date = date '2027-10-31' and c ->> 'month' = '2026-10'),
  'the October 2026 cohort grows on 2027-11-01 with the credits sold on 31 October after the nightly hour'
);
-- Invariant for every stored row: the expired points of all cohorts add up to the expiry rows of the ledger.
select is(
  (select count(*)::int
   from public.loyalty_liability_daily d
   where d.programme_id = (select programme_l from fx)
     and (select coalesce(sum((c ->> 'expired')::int), 0) from jsonb_array_elements(d.breakage_by_cohort) c)
       is distinct from (select coalesce(-sum(l.point_delta), 0) from public.loyalty_ledger l
                         where l.programme_id = d.programme_id and l.entry_kind = 'expire' and l.occurred_at <= d.as_of)),
  0,
  'in every stored row the cohorts'' expired points add up to the expiry rows of the ledger up to that run'
);

-- G-104 F2 (ADR-048): the flows of a row are those of the closed previous local day, from its first
-- moment to the first moment of the row's own day, whatever the hour of the run (oracle: the ledger).
select is(
  (select count(*)::int
   from public.loyalty_liability_daily d
   where d.programme_id = (select programme_l from fx)
     and (d.points_issued, d.points_redeemed, d.points_expired, d.points_clawed_back)
       is distinct from (
         (select coalesce(sum(l.point_delta) filter (where l.point_delta > 0 and l.entry_kind in ('earn', 'adjust') and l.reason is distinct from 'redemption_released'), 0)
            from public.loyalty_ledger l where l.programme_id = d.programme_id
              and l.occurred_at >= ((d.as_of_date - 1)::timestamp at time zone 'Asia/Ho_Chi_Minh') and l.occurred_at < (d.as_of_date::timestamp at time zone 'Asia/Ho_Chi_Minh')),
         (select coalesce(-sum(l.point_delta) filter (where l.entry_kind = 'redeem' or (l.entry_kind = 'adjust' and l.reason = 'redemption_released')), 0)
            from public.loyalty_ledger l where l.programme_id = d.programme_id
              and l.occurred_at >= ((d.as_of_date - 1)::timestamp at time zone 'Asia/Ho_Chi_Minh') and l.occurred_at < (d.as_of_date::timestamp at time zone 'Asia/Ho_Chi_Minh')),
         (select coalesce(-sum(l.point_delta) filter (where l.entry_kind = 'expire'), 0)
            from public.loyalty_ledger l where l.programme_id = d.programme_id
              and l.occurred_at >= ((d.as_of_date - 1)::timestamp at time zone 'Asia/Ho_Chi_Minh') and l.occurred_at < (d.as_of_date::timestamp at time zone 'Asia/Ho_Chi_Minh')),
         (select coalesce(-sum(l.point_delta) filter (where l.entry_kind = 'clawback'), 0)
            from public.loyalty_ledger l where l.programme_id = d.programme_id
              and l.occurred_at >= ((d.as_of_date - 1)::timestamp at time zone 'Asia/Ho_Chi_Minh') and l.occurred_at < (d.as_of_date::timestamp at time zone 'Asia/Ho_Chi_Minh'))
       )),
  0,
  'in every stored row the issued, redeemed, expired and clawed-back points are the ledger''s flows of the previous local day'
);

-- Regression: a re-run of a night replaces its row with the same values.
select app.loyalty_nightly((select tenant_l from fx), timestamptz '2027-11-15 04:00+07');
select is(
  pg_temp.row_doc(date '2027-11-15'),
  (select doc -> 'rows' -> 31 from replay),
  'a re-run of the last nightly run stores the same row again'
);
select is(
  (select count(*)::int from public.loyalty_liability_daily where programme_id = (select programme_l from fx)),
  32,
  'and adds no row'
);

-- Security: no phone, in any form, reaches the stored liability.
select is(
  (select count(*)::int
   from public.loyalty_liability_daily d, members m
   where d.programme_id = (select programme_l from fx)
     and (to_jsonb(d)::text like '%' || m.phone || '%' or to_jsonb(d)::text like '%' || '+84' || substr(m.phone, 2) || '%')),
  0,
  'no member phone appears in any stored liability row'
);

select * from finish();
rollback;
